import { useEffect, useState } from "react";
import LoadingSpinner from "./LoadingSpinner";

export default function TextEditDialog({
  open,
  title,
  label,
  value,
  placeholder,
  onSave,
  onCancel,
  loading,
  required = true,
}) {
  const [draft, setDraft] = useState(value || "");

  useEffect(() => {
    if (value !== undefined) {
      setDraft(value || "");
    }
  }, [value]);

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-modal="true">
      <div className="absolute inset-0 bg-black/50" onClick={() => !loading && onCancel?.()} />
      <div className="brutal-card-static p-6 z-10 w-full max-w-md">
        <div className="space-y-4">
          <h2 className="font-display font-black text-2xl">{title}</h2>
          <label className="block">
            <span className="meta-ink block mb-2">{label}</span>
            <input
              className="brutal-input w-full"
              value={draft}
              placeholder={placeholder}
              onChange={(event) => setDraft(event.target.value)}
              required={required}
            />
          </label>
        </div>
        <div className="mt-5 flex justify-end gap-2">
          <button type="button" className="brutal-btn" onClick={onCancel} disabled={loading}>
            Cancel
          </button>
          <button
            type="button"
            className="brutal-btn accent"
            onClick={() => onSave(draft.trim())}
            disabled={loading || (required && !draft.trim())}
          >
            {loading ? (
              <>
                <LoadingSpinner size={16} /> <span className="ml-2">Save</span>
              </>
            ) : (
              "Save"
            )}
          </button>
        </div>
      </div>
    </div>
  );
}
